(function(){try{importScripts(`https://cdnjs.cloudflare.com/ajax/libs/stockfish.js/10.0.2/stockfish.js`)}catch(e){console.error(`Error importing Stockfish script in worker:`,e)}let e=null;try{typeof STOCKFISH==`function`?e=STOCKFISH():console.warn(`STOCKFISH function is not defined globally.`)}catch(e){console.error(`Failed to instantiate Stockfish:`,e)}e?(e.onmessage=e=>{postMessage(e)},self.onmessage=t=>{e.postMessage(t.data)}):postMessage(`error Stockfish engine not loaded`)})();